        exfilRate = ((exfil.*.btmExfil).*.Ks * Adjust.hydconFactor);
    } else {
        exfilRate = grnampt_getInfil(exfil.*.btmExfil, tStep, 0.0, depth, 3);
    }
    exfilRate = (exfilRate * exfil.*.btmArea);
    if ((depth > exfil.*.bankMinDepth)) {
        area = ((@as(f64, if ((area <= (exfil.*.bankMaxArea))) area else (exfil.*.bankMaxArea))) - exfil.*.btmArea);
        if ((area > 0.0)) {
            if (((exfil.*.btmExfil).*.IMDmax == 0.0)) {
                exfilRate = (exfilRate + ((area * (exfil.*.btmExfil).*.Ks) * Adjust.hydconFactor));
            } else {
