    if ((OldIfaceDate > currentDate)) {
        return 0;
    }
    while (((NewIfaceDate < currentDate) and (NewIfaceDate != (-693594.0)))) {
        setOldIfaceValues();
        readNewIfaceValues();
    }
    if ((NewIfaceDate == (-693594.0))) {
        return 0;
    }
    IfaceFrac = ((currentDate - OldIfaceDate) / (NewIfaceDate - OldIfaceDate));
    IfaceFrac = (@as(f64, if ((0.0 >= IfaceFrac)) 0.0 else IfaceFrac));
    IfaceFrac = (@as(f64, if ((IfaceFrac <= 1.0)) IfaceFrac else 1.0));
    return NumIfaceNodes;
}

