                    return horton_getInfil(&((Infil[ix(j)]).horton), tstep, (rainfall + runon), depth);
        },
        MOD_HORTON => {
                    return modHorton_getInfil(&((Infil[ix(j)]).horton), tstep, (rainfall + runon), depth);
        },
        GREEN_AMPT, MOD_GREEN_AMPT => {
                    return grnampt_getInfil(&((Infil[ix(j)]).grnAmpt), tstep, (rainfall + runon), depth, (Subcatch[ix(j)]).infilModel);
        },
        CURVE_NUMBER => {
                    depth = (depth + (runon * tstep));
