// inflow.c:456
pub fn getPatternFactor(p: i32, month: i32, day: i32, hour: i32) f64 {
    __sw1: {
        switch ((Pattern[ix(p)]).type) {
            MONTHLY_PATTERN => {
                        if (((month >= 0) and (month < 12))) {
                            return ((Pattern[ix(p)]).factor)[ix(month)];
                        }
                        break :__sw1;
            },
            DAILY_PATTERN => {
                        if (((day >= 0) and (day < 7))) {
                            return ((Pattern[ix(p)]).factor)[ix(day)];
                        }
                        break :__sw1;
            },
            HOURLY_PATTERN => {
                        if (((hour >= 0) and (hour < 24))) {
                            return ((Pattern[ix(p)]).factor)[ix(hour)];
                        }
                        break :__sw1;
            },
            WEEKEND_PATTERN => {
                        if (((day == 0) or (day == 6))) {
                            if (((hour >= 0) and (hour < 24))) {
                                return ((Pattern[ix(p)]).factor)[ix(hour)];
                            }
                        }
                        break :__sw1;
            },
            else => {},
        }
    }
    return 1.0;
}

