    _ = &inlet;
    var prevInlet: [*c]TInlet = null;
    _ = &prevInlet;
    if (!(UsesInlets != 0)) {
        return;
    }
    prevInlet = FirstInlet;
    inlet = FirstInlet;
    while ((inlet != null)) {
        inletValid = 0;
        i = inlet.*.linkIndex;
        xsect = &((Link[ix(i)]).xsect);
        inletType = (InletDesigns[ix(inlet.*.designIndex)]).type;
        if ((inletType == 6)) {
            j = (InletDesigns[ix(inlet.*.designIndex)]).customCurve;
            if ((j >= 0)) {
