        } else if ((((xsect.*.type == 5) or (xsect.*.type == 4)) and ((inletType == 4) or (inletType == 5)))) {
            inletValid = 1;
        } else if ((((xsect.*.type == 25) and (inletType != 4)) and (inletType != 5))) {
            inletValid = 1;
        }
        if ((inletValid != 0)) {
            (Node[ix((Link[ix(i)]).node2)]).inlet = 1;
            (Node[ix(inlet.*.nodeIndex)]).inlet = 2;
            inlet.*.backflow = 0.0;
            getConduitGeometry(inlet);
            inlet.*.flowFactor = (((0.56 / n) * R.pow(SL, 0.5)) * R.pow(Sx, 1.67));
            prevInlet = inlet;
            inlet = inlet.*.nextInlet;
        } else {
            report_writeWarningMsg(R.s("WARNING 12: inlet removed due to unsupported shape for Conduit"), (Link[ix(i)]).ID);
            if ((inlet == FirstInlet)) {
                FirstInlet = inlet.*.nextInlet;
                prevInlet = FirstInlet;
                R.free(@as(?*anyopaque, @ptrCast(inlet)));
                inlet = FirstInlet;
            } else {
                prevInlet.*.nextInlet = inlet.*.nextInlet;
                R.free(@as(?*anyopaque, @ptrCast(inlet)));
                inlet = prevInlet.*.nextInlet;
            }
            (Link[ix(i)]).inlet = null;
        }
    }
    getBackflowRatios();
}

// inlet.c:555
pub fn inlet_findCapturedFlows(tStep: f64) void {
    var i: i32 = 0;
    _ = &i;
    var j: i32 = 0;
    _ = &j;
    var m: i32 = 0;
    _ = &m;
    var placement: i32 = 0;
