    _ = &q;
    var inlet: [*c]TInlet = null;
    _ = &inlet;
    if (!(UsesInlets != 0)) {
        return;
    }
    _ = R.memset(@as(?*anyopaque, @ptrCast(InletFlow)), 0, (@as(u64, @bitCast(@as(i64, Nobjects[2]))) *% 8));
    if ((RouteModel != 4)) {
        j = 0;
        while ((j < Nobjects[2])) : (j +%= 1) {
            (Node[ix(j)]).inflow = (@as(f64, if ((0.0 >= ((Node[ix(j)]).newLatFlow))) 0.0 else ((Node[ix(j)]).newLatFlow)));
        }
        i = 0;
        while ((i < Nobjects[3])) : (i +%= 1) {
            (Node[ix((Link[ix(i)]).node2)]).inflow = ((Node[ix((Link[ix(i)]).node2)]).inflow + (@as(f64, if ((0.0 >= ((Link[ix(i)]).newFlow))) 0.0 else ((Link[ix(i)]).newFlow))));
        }
    }
