        i = inlet.*.linkIndex;
        j = (Link[ix(i)]).node2;
        m = inlet.*.nodeIndex;
        placement = getInletPlacement(inlet, j);
        if (((InletDesigns[ix(inlet.*.designIndex)]).type == 6)) {
            q = @abs((Link[ix(i)]).newFlow);
            inlet.*.flowCapture = getCustomCapturedFlow(inlet, q, (Node[ix(j)]).newDepth);
        } else if ((placement == 1)) {
            q = @abs((Link[ix(i)]).newFlow);
            inlet.*.flowCapture = getOnGradeCapturedFlow(inlet, q, (Node[ix(j)]).newDepth);
        } else {
            q = (Node[ix(j)]).inflow;
            inlet.*.flowCapture = getOnSagCapturedFlow(inlet, q, (Node[ix(j)]).newDepth);
        }
        if ((@abs(inlet.*.flowCapture) < 0.0001)) {
            inlet.*.flowCapture = 0.0;
        }
        InletFlow[ix(j)] = (InletFlow[ix(j)] + inlet.*.flowCapture);
        inlet.*.backflow = ((Node[ix(m)]).overflow * inlet.*.backflowRatio);
        if ((@abs(inlet.*.backflow) < 0.0001)) {
            inlet.*.backflow = 0.0;
        }
    }
    inlet = FirstInlet;
    while ((inlet != null)) : (inlet = inlet.*.nextInlet) {
        i = inlet.*.linkIndex;
        j = (Link[ix(i)]).node2;
        m = inlet.*.nodeIndex;
        if (((RouteModel != 4) and (getInletPlacement(inlet, j) == 2))) {
            q = ((Node[ix(j)]).newVolume / tStep);
            q = (q + (@as(f64, if ((((Node[ix(j)]).inflow) >= 0.0)) ((Node[ix(j)]).inflow) else 0.0)));
            if ((InletFlow[ix(j)] > q)) {
                inlet.*.flowCapture = (inlet.*.flowCapture * (q / InletFlow[ix(j)]));
            }
        }
        (Node[ix(j)]).newLatFlow = ((Node[ix(j)]).newLatFlow - (inlet.*.flowCapture - inlet.*.backflow));
        (Node[ix(m)]).newLatFlow = ((Node[ix(m)]).newLatFlow + inlet.*.flowCapture);
        if ((getDateTime(NewRoutingTime) > ReportStart)) {
            updateInletStats(inlet, @abs((Link[ix(i)]).newFlow));
        }
    }
}

