// inlet.c:985
fn updateInletStats(inlet: [*c]TInlet, q: f64) void {
    var qCapture: f64 = 0.0;
    _ = &qCapture;
    var qBackflow: f64 = 0.0;
    _ = &qBackflow;
    var qNet: f64 = 0.0;
    _ = &qNet;
    var qBypass: f64 = 0.0;
    _ = &qBypass;
    var fCapture: f64 = 0.0;
    _ = &fCapture;
    qCapture = inlet.*.flowCapture;
    qBackflow = inlet.*.backflow;
    qNet = (qCapture - qBackflow);
    qBypass = (q - qNet);
    fCapture = 0.0;
    if (((q < 0.001) and (qBackflow <= 0.0))) {
        return;
    }
    (inlet.*.stats).flowPeriods +%= 1;
    if ((qNet > 0.0)) {
        (inlet.*.stats).capturePeriods +%= 1;
        fCapture = (qNet / q);
        fCapture = (@as(f64, if ((fCapture <= 1.0)) fCapture else 1.0));
        (inlet.*.stats).avgFlowCapture = ((inlet.*.stats).avgFlowCapture + fCapture);
        if ((qBypass > 0.001)) {
            (inlet.*.stats).bypassFreq += 1.0;
        }
    } else {
        (inlet.*.stats).backflowPeriods +%= 1;
    }
    if ((q > (inlet.*.stats).peakFlow)) {
        (inlet.*.stats).peakFlow = q;
        (inlet.*.stats).peakFlowCapture = (fCapture * 100.0);
    }
}

