// inlet.c:1200
fn getFlowSpread(Q_2: f64) f64 {
    var iter: i32 = 0;
    _ = &iter;
    var f: f64 = 0.0;
    _ = &f;
    var f1: f64 = 0.0;
    _ = &f1;
    var Sr: f64 = 0.0;
    _ = &Sr;
    var Ts1: f64 = 0.0;
    _ = &Ts1;
    var Ts2: f64 = 0.0;
    _ = &Ts2;
    var Tw: f64 = 0.0;
    _ = &Tw;
    var Qs: f64 = 0.0;
    _ = &Qs;
    var Eo: f64 = 0.0;
    _ = &Eo;
    f = Qfactor;
    if ((a == 0.0)) {
        Ts1 = R.pow((Q_2 / f), 0.375);
    } else {
        f1 = (f * R.pow(((a / W) / Sx), 1.67));
        Tw = R.pow((Q_2 / f1), 0.375);
        if ((Tw <= W)) {
            Ts1 = Tw;
        } else {
            Sr = ((Sx + (a / W)) / Sx);
            iter = 1;
            Ts1 = (R.pow((Q_2 / f), 0.375) - W);
            if ((Ts1 <= 0.0)) {
                Ts1 = (Tw - W);
            }
            while ((iter < 11)) {
                Eo = getEo(Sr, Ts1, W);
                Qs = ((1.0 - Eo) * Q_2);
                Ts2 = R.pow((Qs / f), 0.375);
                if ((@abs((Ts2 - Ts1)) < 0.01)) {
                    break;
                }
                Ts1 = Ts2;
                iter +%= 1;
            }
            Ts1 = (Ts2 + W);
        }
    }
    return (@as(f64, if ((Ts1 <= Tcrown)) Ts1 else Tcrown));
