            if ((newsect >= 0)) {
                if ((sect == 22)) {
                    transect_validate((Nobjects[10] -% 1));
                }
                sect = newsect;
                continue;
            } else {
                inperr = error_setInpError(205, Tok[0]);
                report_writeInputErrorMsg(inperr, sect, &line[0], lineCount);
                errsum +%= 1;
                break;
            }
        } else {
            inperr = parseLine(sect, &line[0]);
            if ((inperr > 0)) {
                errsum +%= 1;
                if ((errsum > MAXERRS)) {
                    report_writeLine(R.s("\n  Maximum error count exceeded."));
                } else {
                    report_writeInputErrorMsg(inperr, sect, &line[0], lineCount);
                }
            }
        }
        if ((errsum > MAXERRS)) {
            break;
        }
    }
    if ((errsum > 0)) {
        ErrorCode = 200;
    }
    return ErrorCode;
}

