// input.c:637
fn readControl(tok: [*c][*c]i8, ntoks: i32) i32 {
    var index: i32 = 0;
    _ = &index;
    var keyword: i32 = 0;
    _ = &keyword;
    if ((ntoks < 2)) {
        return error_setInpError(203, R.s(""));
    }
    if ((match(tok[0], R.s("VARIABLE")) != 0)) {
        return controls_addVariable(@as([*c][*c]i8, @ptrCast(@alignCast(&tok[0]))), ntoks);
    }
    if ((match(tok[0], R.s("EXPRESSION")) != 0)) {
        return controls_addExpression(@as([*c][*c]i8, @ptrCast(@alignCast(&tok[0]))), ntoks);
    }
    keyword = findmatch(tok[0], &RuleKeyWords[0]);
    if ((keyword < 0)) {
        return error_setInpError(205, tok[0]);
    }
    if ((keyword == 0)) {
        if (!(project_addObject(9, tok[1], Mobjects[9]) != 0)) {
            return error_setInpError(207, Tok[1]);
        }
        Mobjects[9] +%= 1;
    }
    index = (Mobjects[9] -% 1);
    if ((index < 0)) {
        return error_setInpError(217, R.s(""));
    }
    return controls_addRuleClause(index, keyword, &Tok[0], Ntokens);
}

