// input.c:755
fn readEvent(tok: [*c][*c]i8, ntoks: i32) i32 {
    var x: [4]f64 = std.mem.zeroes([4]f64);
    _ = &x;
    if ((ntoks < 4)) {
        return error_setInpError(203, R.s(""));
    }
    if (!(datetime_strToDate(tok[0], &x[0]) != 0)) {
        return error_setInpError(213, tok[0]);
    }
    if (!(datetime_strToTime(tok[1], &x[1]) != 0)) {
        return error_setInpError(213, tok[1]);
    }
    if (!(datetime_strToDate(tok[2], &x[2]) != 0)) {
        return error_setInpError(213, tok[2]);
    }
    if (!(datetime_strToTime(tok[3], &x[3]) != 0)) {
        return error_setInpError(213, tok[3]);
    }
    (Event[ix(Mevents)]).start = (x[0] + x[1]);
    (Event[ix(Mevents)]).end = (x[2] + x[3]);
    if (((Event[ix(Mevents)]).start >= (Event[ix(Mevents)]).end)) {
        return error_setInpError(213, R.s(" - start date exceeds end date"));
    }
    Mevents +%= 1;
    return 0;
}

