    }
    i = k;
    j = 0;
    while ((substr[ix(j)] != 0)) : ({ i +%= 1; j +%= 1; }) {
        if ((!(str[ix(i)] != 0) or ((@as(i32, if (((@as(i32, (str[ix(i)])) >= 97) and (@as(i32, (str[ix(i)])) <= 122))) (@as(i32, (str[ix(i)])) & (-33)) else @as(i32, (str[ix(i)])))) != (@as(i32, if (((@as(i32, (substr[ix(j)])) >= 97) and (@as(i32, (substr[ix(j)])) <= 122))) (@as(i32, (substr[ix(j)])) & (-33)) else @as(i32, (substr[ix(j)]))))))) {
            return 0;
        }
    }
    return 1;
}

