fn getTokens(s_arg: [*c]i8) i32 {
    var s: [*c]i8 = s_arg;
    _ = &s;
    var len: i32 = 0;
    _ = &len;
    var n_2: i32 = 0;
    _ = &n_2;
    var m: i32 = 0;
    _ = &m;
    var c: [*c]i8 = null;
    _ = &c;
    n_2 = 0;
    while ((n_2 < 40)) : (n_2 +%= 1) {
        Tok[ix(n_2)] = null;
    }
    n_2 = 0;
    c = R.strchr(s, 59);
    if ((c != null)) {
        c.* = 0;
    }
    len = @as(i32, @bitCast(@as(u32, @truncate(R.strlen(s)))));
    while (((len > 0) and (n_2 < 40))) {
        m = @as(i32, @bitCast(@as(u32, @truncate(R.strcspn(s, R.s(" \t\n\r"))))));
        if ((m == 0)) {
            s += 1;
        } else {
            if ((@as(i32, s.*) == 34)) {
                s += 1;
                len -%= 1;
                m = @as(i32, @bitCast(@as(u32, @truncate(R.strcspn(s, R.s("\"\n"))))));
            }
            s[ix(m)] = 0;
            Tok[ix(n_2)] = s;
            n_2 +%= 1;
            s = R.padd(s, (m +% 1));
        }
        len -%= (m +% 1);
    }
    return n_2;
}

