// kinwave.c:57
pub fn kinwave_execute(j: i32, qinflow: [*c]f64, qoutflow: [*c]f64, tStep: f64) i32 {
    var k: i32 = 0;
    _ = &k;
    var result: i32 = 0;
    _ = &result;
    var dxdt: f64 = 0.0;
    _ = &dxdt;
    var dq: f64 = 0.0;
    _ = &dq;
    var ain: f64 = 0.0;
    _ = &ain;
    var aout: f64 = 0.0;
    _ = &aout;
    var qin: f64 = 0.0;
    _ = &qin;
    var qout: f64 = 0.0;
    _ = &qout;
    var a1: f64 = 0.0;
    _ = &a1;
    var a2: f64 = 0.0;
    _ = &a2;
    var q1: f64 = 0.0;
    _ = &q1;
    var q2: f64 = 0.0;
    _ = &q2;
    var q3: f64 = 0.0;
    _ = &q3;
    result = 1;
    qoutflow.* = (qinflow.*);
    if (((Link[ix(j)]).type != 0)) {
        return result;
    }
    if ((((Link[ix(j)]).xsect).type == 0)) {
        return result;
    }
    pXsect = &((Link[ix(j)]).xsect);
    Qfull = (Link[ix(j)]).qFull;
    Afull = ((Link[ix(j)]).xsect).aFull;
    k = (Link[ix(j)]).subIndex;
    Beta1 = ((Conduit[ix(k)]).beta / Qfull);
    q1 = ((Conduit[ix(k)]).q1 / Qfull);
    q2 = ((Conduit[ix(k)]).q2 / Qfull);
    qin = (((qinflow.*) / @as(f64, @floatFromInt(@as(i32, (Conduit[ix(k)]).barrels)))) / Qfull);
    q3 = (link_getLossRate(j, 2, (qin * Qfull), tStep) / Qfull);
    a1 = ((Conduit[ix(k)]).a1 / Afull);
    a2 = ((Conduit[ix(k)]).a2 / Afull);
    if ((qin >= 1.0)) {
        ain = 1.0;
    } else {
        ain = (xsect_getAofS(pXsect, (qin / Beta1)) / Afull);
    }
    if (((qin <= 1e-06) and (q2 <= 1e-06))) {
        qout = 0.0;
        aout = 0.0;
    } else {
        dxdt = (((link_getLength(j) / tStep) * Afull) / Qfull);
        dq = (q2 - q1);
        C1 = ((dxdt * WT) / WX);
        C2 = ((1.0 - WT) * (ain - a1));
        C2 = (C2 - (WT * a2));
        C2 = ((C2 * dxdt) / WX);
        C2 = ((C2 + (((1.0 - WX) / WX) * dq)) - qin);
        C2 = (C2 + (q3 / WX));
        aout = a2;
        result = solveContinuity(qin, ain, &aout);
        if ((result == (-1))) {
            report_writeErrorMsg(103, (Link[ix(j)]).ID);
            return 1;
        }
        if ((result <= 0)) {
            result = 1;
        }
        qout = (Beta1 * xsect_getSofA(pXsect, (aout * Afull)));
        if ((qin > 1.0)) {
            qin = 1.0;
        }
    }
    (Conduit[ix(k)]).q1 = (qin * Qfull);
    (Conduit[ix(k)]).a1 = (ain * Afull);
    (Conduit[ix(k)]).q2 = (qout * Qfull);
    (Conduit[ix(k)]).a2 = (aout * Afull);
    (Conduit[ix(k)]).fullState = link_getFullState((Conduit[ix(k)]).a1, (Conduit[ix(k)]).a2, Afull);
    qinflow.* = ((Conduit[ix(k)]).q1 * @as(f64, @floatFromInt(@as(i32, (Conduit[ix(k)]).barrels))));
    qoutflow.* = ((Conduit[ix(k)]).q2 * @as(f64, @floatFromInt(@as(i32, (Conduit[ix(k)]).barrels))));
    return result;
}

// kinwave.c:170
fn solveContinuity(qin: f64, ain: f64, aout: [*c]f64) i32 {
    var n_2: i32 = 0;
    _ = &n_2;
    var aLo: f64 = 0.0;
    _ = &aLo;
    var aHi: f64 = 0.0;
    _ = &aHi;
    var aTmp: f64 = 0.0;
    _ = &aTmp;
    var fLo: f64 = 0.0;
    _ = &fLo;
    var fHi: f64 = 0.0;
    _ = &fHi;
    var tol: f64 = 0.0;
    _ = &tol;
    tol = EPSIL;
    aHi = 1.0;
    fHi = ((1.0 + C1) + C2);
    aLo = (xsect_getAmax(pXsect) / Afull);
    if ((aLo < aHi)) {
        fLo = (((Beta1 * pXsect.*.sMax) + (C1 * aLo)) + C2);
    } else {
        fLo = fHi;
    }
    if (((fHi * fLo) > 0.0)) {
        aHi = aLo;
        fHi = fLo;
        aLo = 0.0;
        fLo = C2;
    }
    if (((fHi * fLo) <= 0.0)) {
        if (((aout.* < aLo) or (aout.* > aHi))) {
            aout.* = (0.5 * (aLo + aHi));
        }
        if ((fLo > fHi)) {
            aTmp = aLo;
            aLo = aHi;
            aHi = aTmp;
        }
        n_2 = findroot_Newton(aLo, aHi, aout, tol, &evalContinuity, null);
        if ((n_2 <= 0)) {
            n_2 = (-1);
        }
    } else if ((fLo < 0.0)) {
        if ((qin > 1.0)) {
            aout.* = ain;
        } else {
            aout.* = 1.0;
        }
        n_2 = (-2);
    } else if ((fLo > 0.0)) {
        aout.* = 0.0;
        n_2 = (-3);
    } else {
        n_2 = (-1);
    }
    return n_2;
}

// kinwave.c:261
fn evalContinuity(a_2: f64, f: [*c]f64, df: [*c]f64, p: ?*anyopaque) void {
    _ = p;
    f.* = (((Beta1 * xsect_getSofA(pXsect, (a_2 * Afull))) + (C1 * a_2)) + C2);
    df.* = (((Beta1 * Afull) * xsect_getdSdA(pXsect, (a_2 * Afull))) + C1);
}

