pub fn landuse_readParams(j: i32, tok: [*c][*c]i8, ntoks: i32) i32 {
    var id: [*c]i8 = null;
    _ = &id;
    if ((ntoks < 1)) {
        return error_setInpError(203, R.s(""));
    }
    id = project_findID(5, tok[0]);
    if ((id == null)) {
        return error_setInpError(209, tok[0]);
    }
    (Landuse[ix(j)]).ID = id;
    if ((ntoks > 1)) {
        if ((ntoks < 4)) {
