// lid.c:304
pub fn lid_delete() void {
    var j: i32 = 0;
    _ = &j;
    j = 0;
    while ((j < GroupCount)) : (j +%= 1) {
        freeLidGroup(j);
    }
    {
        if ((LidGroups != null)) {
            R.free(@as(?*anyopaque, @ptrCast(LidGroups)));
            LidGroups = null;
        }
    }
    j = 0;
    while ((j < LidCount)) : (j +%= 1) {
        if (((LidProcs[ix(j)]).drainRmvl != null)) {
            R.free(@as(?*anyopaque, @ptrCast((LidProcs[ix(j)]).drainRmvl)));
            (LidProcs[ix(j)]).drainRmvl = null;
        }
    }
    {
        if ((LidProcs != null)) {
            R.free(@as(?*anyopaque, @ptrCast(LidProcs)));
            LidProcs = null;
        }
    }
    GroupCount = 0;
    LidCount = 0;
}

// lid.c:322
fn freeLidGroup(j: i32) void {
    var lidGroup: [*c]LidGroup = null;
    _ = &lidGroup;
    var lidList: [*c]TLidList = null;
    _ = &lidList;
    var lidUnit: [*c]TLidUnit = null;
    _ = &lidUnit;
    var nextLidUnit: [*c]TLidList = null;
    _ = &nextLidUnit;
    lidGroup = LidGroups[ix(j)];
    if ((lidGroup == null)) {
        return;
    }
    lidList = lidGroup.*.lidList;
    while ((lidList != null)) {
        lidUnit = lidList.*.lidUnit;
        if ((lidUnit.*.rptFile != null)) {
            if (((lidUnit.*.rptFile).*.file != null)) {
                _ = R.fclose((lidUnit.*.rptFile).*.file);
            }
            R.free(@as(?*anyopaque, @ptrCast(lidUnit.*.rptFile)));
        }
        nextLidUnit = lidList.*.nextLidUnit;
        R.free(@as(?*anyopaque, @ptrCast(lidUnit)));
        R.free(@as(?*anyopaque, @ptrCast(lidList)));
        lidList = nextLidUnit;
    }
    R.free(@as(?*anyopaque, @ptrCast(lidGroup)));
    LidGroups[ix(j)] = null;
}

// lid.c:355
pub fn lid_readProcParams(toks: [*c][*c]i8, ntoks: i32) i32 {
    var j: i32 = 0;
    _ = &j;
    var m: i32 = 0;
    _ = &m;
    if ((ntoks < 2)) {
        return error_setInpError(203, R.s(""));
    }
    j = project_findObject(15, toks[0]);
    if ((j < 0)) {
        return error_setInpError(209, toks[0]);
    }
    if (((LidProcs[ix(j)]).ID == null)) {
        (LidProcs[ix(j)]).ID = project_findID(15, toks[0]);
    }
    m = findmatch(toks[1], &LidTypeWords[0]);
    if ((m >= 0)) {
        (LidProcs[ix(j)]).lidType = m;
        return 0;
    } else {
        m = findmatch(toks[1], &LidLayerWords[0]);
    }
    switch (m) {
        SURF => {
                    return readSurfaceData(j, &toks[0], ntoks);
        },
        SOIL => {
                    return readSoilData(j, &toks[0], ntoks);
        },
        STOR => {
                    return readStorageData(j, &toks[0], ntoks);
        },
        PAVE => {
                    return readPavementData(j, &toks[0], ntoks);
        },
        5 => {
                    return readDrainData(j, &toks[0], ntoks);
        },
        DRAINMAT => {
                    return readDrainMatData(j, &toks[0], ntoks);
        },
        REMOVALS => {
                    return readRemovalsData(j, &toks[0], ntoks);
        },
        else => {},
    }
    return error_setInpError(205, toks[1]);
}

