    fname = null;
    drainSubcatch = (-1);
    drainNode = (-1);
    if ((ntoks < 8)) {
        return error_setInpError(203, R.s(""));
    }
    j = project_findObject(1, toks[0]);
    if ((j < 0)) {
        return error_setInpError(209, toks[0]);
    }
    k = project_findObject(15, toks[1]);
    if ((k < 0)) {
        return error_setInpError(209, toks[1]);
    }
    n_2 = R.atoi(toks[2]);
    if ((n_2 < 0)) {
        return error_setInpError(211, toks[2]);
    }
    if ((n_2 == 0)) {
        return 0;
    }
    i = 3;
    while ((i <= 7)) : (i +%= 1) {
        if ((!(getDouble(toks[ix(i)], &(x[ix((i -% 3))])) != 0) or (x[ix((i -% 3))] < 0.0))) {
            return error_setInpError(211, toks[ix(i)]);
        }
    }
    i = 2;
    while ((i <= 3)) : (i +%= 1) {
        if ((x[ix(i)] > 100.0)) {
            return error_setInpError(211, toks[ix((i +% 3))]);
        }
    }
    if (((ntoks >= 9) and (R.strcmp(toks[8], R.s("*")) != 0))) {
        fname = toks[8];
    }
    if (((ntoks >= 10) and (R.strcmp(toks[9], R.s("*")) != 0))) {
        drainSubcatch = project_findObject(1, toks[9]);
        if ((drainSubcatch < 0)) {
            drainNode = project_findObject(2, toks[9]);
            if ((drainNode < 0)) {
                return error_setInpError(209, toks[9]);
            }
        }
    }
    x[5] = 0.0;
    if ((ntoks >= 11)) {
        if (((!(getDouble(toks[10], &x[5]) != 0) or (x[5] < 0.0)) or (x[5] > 100.0))) {
            return error_setInpError(211, toks[10]);
