// lid.c:499
fn addLidUnit(j: i32, k: i32, n_2: i32, x: [*c]f64, fname: [*c]i8, drainSubcatch: i32, drainNode: i32) i32 {
    var lidUnit: [*c]TLidUnit = null;
    _ = &lidUnit;
    var lidList: [*c]TLidList = null;
    _ = &lidList;
    var lidGroup: [*c]LidGroup = null;
    _ = &lidGroup;
    lidGroup = LidGroups[ix(j)];
    if (!(lidGroup != null)) {
        lidGroup = @as([*c]LidGroup, @ptrCast(@alignCast(R.malloc(40))));
        if (!(lidGroup != null)) {
            return error_setInpError(101, R.s(""));
        }
        lidGroup.*.lidList = null;
        LidGroups[ix(j)] = lidGroup;
    }
    lidUnit = @as([*c]TLidUnit, @ptrCast(@alignCast(R.malloc(312))));
    if (!(lidUnit != null)) {
        return error_setInpError(101, R.s(""));
    }
    lidUnit.*.rptFile = null;
    lidList = @as([*c]TLidList, @ptrCast(@alignCast(R.malloc(16))));
    if (!(lidList != null)) {
        R.free(@as(?*anyopaque, @ptrCast(lidUnit)));
        return error_setInpError(101, R.s(""));
    }
    lidList.*.lidUnit = lidUnit;
    lidList.*.nextLidUnit = lidGroup.*.lidList;
    lidGroup.*.lidList = lidList;
    lidUnit.*.lidIndex = k;
    lidUnit.*.number = n_2;
    lidUnit.*.area = (x[0] / ((UCF(3)) * (UCF(3))));
    lidUnit.*.fullWidth = (x[1] / UCF(3));
    lidUnit.*.initSat = (x[2] / 100.0);
    lidUnit.*.fromImperv = (x[3] / 100.0);
    lidUnit.*.toPerv = @as(i32, @intFromBool((x[4] > 0.0)));
    lidUnit.*.fromPerv = (x[5] / 100.0);
    lidUnit.*.drainSubcatch = drainSubcatch;
    lidUnit.*.drainNode = drainNode;
    if ((fname != null)) {
        if (!(createLidRptFile(lidUnit, fname) != 0)) {
            return error_setInpError(305, fname);
        }
    }
    return 0;
}

// lid.c:567
fn createLidRptFile(lidUnit: [*c]TLidUnit, fname: [*c]i8) i32 {
    var rptFile: [*c]TLidRptFile = null;
    _ = &rptFile;
    rptFile = @as([*c]TLidRptFile, @ptrCast(@alignCast(R.malloc(272))));
    if ((rptFile == null)) {
        return 0;
    }
    lidUnit.*.rptFile = rptFile;
    rptFile.*.file = R.fopen(fname, R.s("wt"));
    if ((rptFile.*.file == null)) {
        return 0;
    }
    return 1;
}

