    _ = R.fprintf(Frpt.file, R.s("\n"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  *******************"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  LID Control Summary"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  *******************"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n                                   No. of        Unit        Unit      %% Area    %% Imperv      %% Perv"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  Subcatchment     LID Control      Units        Area       Width     Covered     Treated     Treated"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  ---------------------------------------------------------------------------------------------------"), .{  });
