            _ = R.fprintf(Frpt.file, R.s("\n  %-16s %-16s"), .{ @as([*c]i8, (Subcatch[ix(j)]).ID), @as([*c]i8, (LidProcs[ix(k)]).ID) });
            _ = R.fprintf(Frpt.file, R.s("%6d  %10.2f  %10.2f  %10.2f  %10.2f  %10.2f"), .{ @as(i32, lidUnit.*.number), @as(f64, (lidUnit.*.area * ((UCF(3)) * (UCF(3))))), @as(f64, (lidUnit.*.fullWidth * UCF(3))), @as(f64, pctArea), @as(f64, (lidUnit.*.fromImperv * 100.0)), @as(f64, (lidUnit.*.fromPerv * 100.0)) });
            lidList = lidList.*.nextLidUnit;
