// lid.c:932
fn validateLidProc(j: i32) void {
    var layerMissing: i32 = 0;
    _ = &layerMissing;
    layerMissing = 0;
    if (((LidProcs[ix(j)]).lidType < 0)) {
        report_writeErrorMsg(183, (LidProcs[ix(j)]).ID);
        return;
    }
    __sw1: {
        switch ((LidProcs[ix(j)]).lidType) {
            BIO_CELL, RAIN_GARDEN => {
                        if ((((LidProcs[ix(j)]).soil).thickness <= 0.0)) {
                            layerMissing = 1;
                        }
                        break :__sw1;
            },
            GREEN_ROOF => {
                        if ((((LidProcs[ix(j)]).soil).thickness <= 0.0)) {
                            layerMissing = 1;
                        }
                        if ((((LidProcs[ix(j)]).drainMat).thickness <= 0.0)) {
                            layerMissing = 1;
