fn modpuls_solve(n_2: i32, x: [*c]f64, xOld: [*c]f64, xPrev: [*c]f64, xMin: [*c]f64, xMax: [*c]f64, xTol: [*c]f64, qOld: [*c]f64, q: [*c]f64, dt: f64, omega: f64, derivs: ?*const fn ([*c]f64, [*c]f64) void) i32 {
