    _ = &dir;
    n1 = (Link[ix(j)]).node1;
    n2 = (Link[ix(j)]).node2;
    k = (Link[ix(j)]).subIndex;
    if ((RouteModel == 4)) {
        h1 = ((Node[ix(n1)]).newDepth + (Node[ix(n1)]).invertElev);
        h2 = ((Node[ix(n2)]).newDepth + (Node[ix(n2)]).invertElev);
    } else {
        h1 = ((Node[ix(n1)]).newDepth + (Node[ix(n1)]).invertElev);
        h2 = (Node[ix(n1)]).invertElev;
    }
    dir = @as(f64, if ((h1 >= h2)) 1.0 else (-1.0));
    y1 = (Node[ix(n1)]).newDepth;
    if ((dir < 0.0)) {
        y1 = h1;
        h1 = h2;
        h2 = y1;
        y1 = (Node[ix(n2)]).newDepth;
    }
    hcrest = ((Node[ix(n1)]).invertElev + (Link[ix(j)]).offset1);
    if ((((Outlet[ix(k)]).curveType == 1) and (RouteModel == 4))) {
        head = (h1 - (@as(f64, if ((h2 >= hcrest)) h2 else hcrest)));
    } else {
        head = (h1 - hcrest);
