    if ((((head <= 0.0001) or (y1 <= 0.0001)) or (link_setFlapGate(j, n1, n2, dir) != 0))) {
        (Link[ix(j)]).newDepth = 0.0;
        (Link[ix(j)]).flowClass = 0;
