pub fn qualrout_execute(tStep: f64) void {
    var i: i32 = 0;
    _ = &i;
    var j: i32 = 0;
    _ = &j;
    var qIn: f64 = 0.0;
    _ = &qIn;
    var vAvg: f64 = 0.0;
    _ = &vAvg;
    i = 0;
