    }
    j = 0;
    while ((j < Nobjects[2])) : (j +%= 1) {
        (Node[ix(j)]).qualInflow = (Node[ix(j)]).inflow;
        qIn = (Node[ix(j)]).qualInflow;
        vAvg = (((Node[ix(j)]).oldVolume + (Node[ix(j)]).newVolume) / 2.0);
        if (((Node[ix(j)]).treatment != null)) {
            if ((qIn < 1e-10)) {
                qIn = 0.0;
            }
            treatmnt_setInflow(qIn, (Node[ix(j)]).newQual);
        }
        if ((((Node[ix(j)]).type == 2) or ((Node[ix(j)]).oldVolume > ZeroVolume))) {
            findStorageQual(j, tStep);
        } else {
            findNodeQual(j);
        }
        if (((Node[ix(j)]).treatment != null)) {
            treatmnt_treat(j, qIn, vAvg, tStep);
        }
    }
    i = 0;
    while ((i < Nobjects[3])) : (i +%= 1) {
        findLinkQual(i, tStep);
    }
}

