fn getMixedQual(c_arg: f64, v1: f64, wIn: f64, qIn: f64, tStep: f64) f64 {
    var c: f64 = c_arg;
    _ = &c;
    var vIn: f64 = 0.0;
    _ = &vIn;
    var cIn: f64 = 0.0;
    _ = &cIn;
    var cMax: f64 = 0.0;
    _ = &cMax;
    if ((qIn <= 1e-10)) {
        return c;
    }
    vIn = (qIn * tStep);
    cIn = ((wIn * tStep) / vIn);
    cMax = (@as(f64, if ((c >= cIn)) c else cIn));
    c = (((c * v1) + (wIn * tStep)) / (v1 + vIn));
    c = (@as(f64, if ((c <= cMax)) c else cMax));
    c = (@as(f64, if ((c >= 0.0)) c else 0.0));
    return c;
}

