                excessDepth = applyIA(j, k, gageDate, @as(f64, @floatFromInt(rainInterval)), rainDepth);
                updateDryPeriod(j, k, excessDepth, rainInterval);
                i = (((UHGroup[ix(j)]).uh)[ix(k)]).period;
                if ((i >= (((UHGroup[ix(j)]).uh)[ix(k)]).maxPeriods)) {
