    ia = ((((UnitHyd[ix(j)]).iaMax)[ix(m)])[ix(k)] - (((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed);
    ia = (@as(f64, if ((ia >= 0.0)) ia else 0.0));
    if ((rainDepth > 0.0)) {
        netRainDepth = (rainDepth - ia);
        netRainDepth = (@as(f64, if ((netRainDepth >= 0.0)) netRainDepth else 0.0));
        ia = (rainDepth - netRainDepth);
        (((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed = ((((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed + ia);
    } else {
        (((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed = ((((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed - ((dt / 86400.0) * (((UnitHyd[ix(j)]).iaRecov)[ix(m)])[ix(k)]));
        (((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed = (@as(f64, if ((((((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed) >= 0.0)) ((((UHGroup[ix(j)]).uh)[ix(k)]).iaUsed) else 0.0));
        netRainDepth = 0.0;
    }
    return netRainDepth;
}

