        (((UHGroup[ix(j)]).uh)[ix(k)]).hasPastRain = 1;
    } else {
        (((UHGroup[ix(j)]).uh)[ix(k)]).drySeconds +%= @as(i64, rainInterval);
        if (((((UHGroup[ix(j)]).uh)[ix(k)]).drySeconds >= @as(i64, (rainInterval *% (((UHGroup[ix(j)]).uh)[ix(k)]).maxPeriods)))) {
            (((UHGroup[ix(j)]).uh)[ix(k)]).hasPastRain = 0;
