// rdii.c:1358
fn getUnitHydConvol(j: i32, k: i32, rainInterval: i32) f64 {
    var i: i32 = 0;
    _ = &i;
    var m: i32 = 0;
    _ = &m;
    var p: i32 = 0;
    _ = &p;
    var pMax: i32 = 0;
    _ = &pMax;
    var t: f64 = 0.0;
    _ = &t;
    var u: f64 = 0.0;
    _ = &u;
    var v: f64 = 0.0;
    _ = &v;
    var rdii: f64 = 0.0;
    _ = &rdii;
    var uh: [*c]TUHData = null;
    _ = &uh;
    rdii = 0.0;
    uh = &(((UHGroup[ix(j)]).uh)[ix(k)]);
    i = (uh.*.period -% 1);
    if ((i < 0)) {
        i = (uh.*.maxPeriods -% 1);
    }
    pMax = uh.*.maxPeriods;
    p = 1;
    while ((p < pMax)) {
        v = (uh.*.pastRain)[ix(i)];
        m = @as(i32, (uh.*.pastMonth)[ix(i)]);
        if ((v > 0.0)) {
            t = ((@as(f64, @floatFromInt(p)) - 0.5) * @as(f64, @floatFromInt(rainInterval)));
            u = (getUnitHydOrd(j, m, k, t) * (((UnitHyd[ix(j)]).r)[ix(m)])[ix(k)]);
            rdii = (rdii + (u * v));
        }
        p = (p +% 1);
        i = (i -% 1);
        if ((i < 0)) {
            i = (uh.*.maxPeriods -% 1);
        }
    }
    return rdii;
}

// rdii.c:1411
fn getUnitHydOrd(h: i32, m: i32, k: i32, t: f64) f64 {
    var qPeak: f64 = 0.0;
    _ = &qPeak;
    var f: f64 = 0.0;
    _ = &f;
    var t1: f64 = 0.0;
    _ = &t1;
    var t2: f64 = 0.0;
    _ = &t2;
    var tBase: f64 = 0.0;
    _ = &tBase;
    tBase = @as(f64, @floatFromInt((((UnitHyd[ix(h)]).tBase)[ix(m)])[ix(k)]));
    if ((t >= tBase)) {
        return 0.0;
    }
    qPeak = ((2.0 / tBase) * 3600.0);
    t1 = @as(f64, @floatFromInt((((UnitHyd[ix(h)]).tPeak)[ix(m)])[ix(k)]));
    t2 = (tBase - t1);
    if ((t <= t1)) {
        f = (t / t1);
    } else {
        f = (1.0 - ((t - t1) / t2));
    }
    return ((@as(f64, if ((f >= 0.0)) f else 0.0)) * qPeak);
}

