    if ((ntoks < 2)) {
        return error_setInpError(203, R.s(""));
    }
    k = @as(i8, @truncate(findmatch(tok[0], &ReportWords[0])));
    if ((@as(i32, k) < 0)) {
        return error_setInpError(205, tok[0]);
    }
    if (((@as(i32, k) < 2) or (@as(i32, k) > 4))) {
        m = findmatch(tok[1], &NoYesWords[0]);
        if (((m < 0) or (m > 1))) {
            return error_setInpError(205, tok[1]);
        }
        switch (@as(i32, k)) {
            0 => {
                        RptFlags.disabled = @as(i8, @truncate(m));
                        return 0;
            },
            1 => {
                        RptFlags.input = @as(i8, @truncate(m));
                        return 0;
            },
            5 => {
                        RptFlags.continuity = @as(i8, @truncate(m));
                        return 0;
            },
            6 => {
                        RptFlags.flowStats = @as(i8, @truncate(m));
                        return 0;
            },
            7 => {
                        RptFlags.controls = @as(i8, @truncate(m));
                        return 0;
            },
            8 => {
                        RptFlags.averages = @as(i8, @truncate(m));
                        return 0;
            },
            9 => {
                        return 0;
            },
            else => {
                        return error_setInpError(205, tok[1]);
            },
        }
    } else {
        __sw2: {
            switch (@as(i32, k)) {
                2 => {
                            m = 1;
                            break :__sw2;
                },
                3 => {
                            m = 2;
                            break :__sw2;
                },
                4 => {
                            m = 3;
                            break :__sw2;
                },
                else => {},
            }
        }
    }
    if ((strcomp(tok[1], R.s("NONE")) != 0)) {
        k = 0;
    } else if ((strcomp(tok[1], R.s("ALL")) != 0)) {
        k = 1;
    } else {
        k = 2;
        t = 1;
        while ((t < ntoks)) : (t +%= 1) {
            j = project_findObject(m, tok[ix(t)]);
            if ((j < 0)) {
                return error_setInpError(209, tok[ix(t)]);
            }
            __sw3: {
                switch (m) {
                    SUBCATCH => {
                                (Subcatch[ix(j)]).rptFlag = 1;
                                break :__sw3;
                    },
                    NODE => {
                                (Node[ix(j)]).rptFlag = 1;
                                break :__sw3;
                    },
                    LINK => {
                                (Link[ix(j)]).rptFlag = 1;
                                break :__sw3;
                    },
                    else => {},
                }
            }
        }
    }
    __sw4: {
        switch (m) {
            SUBCATCH => {
                        RptFlags.subcatchments = k;
                        break :__sw4;
            },
            NODE => {
                        RptFlags.nodes = k;
                        break :__sw4;
            },
            LINK => {
                        RptFlags.links = k;
                        break :__sw4;
            },
            else => {},
        }
    }
    return 0;
}

