        _ = R.fprintf(Frpt.file, R.s("\n  Infiltration Method ...... %s"), .{ @as([*c]i8, InfilModelWords[ix(InfilModel)]) });
    }
    if ((Nobjects[3] > 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Flow Routing Method ...... %s"), .{ @as([*c]i8, RouteModelWords[ix(RouteModel)]) });
    }
    if ((RouteModel == 4)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Surcharge Method ......... %s"), .{ @as([*c]i8, SurchargeWords[ix(SurchargeMethod)]) });
    }
    datetime_dateToStr(StartDate, &str[0]);
    _ = R.fprintf(Frpt.file, R.s("\n  Starting Date ............ %s"), .{ @as([*c]i8, &str[0]) });
    datetime_timeToStr(StartTime, &str[0]);
    _ = R.fprintf(Frpt.file, R.s(" %s"), .{ @as([*c]i8, &str[0]) });
    datetime_dateToStr(EndDate, &str[0]);
    _ = R.fprintf(Frpt.file, R.s("\n  Ending Date .............. %s"), .{ @as([*c]i8, &str[0]) });
    datetime_timeToStr(EndTime, &str[0]);
    _ = R.fprintf(Frpt.file, R.s(" %s"), .{ @as([*c]i8, &str[0]) });
    _ = R.fprintf(Frpt.file, R.s("\n  Antecedent Dry Days ...... %.1f"), .{ @as(f64, StartDryDays) });
    datetime_timeToStr(datetime_encodeTime(0, 0, ReportStep), &str[0]);
    _ = R.fprintf(Frpt.file, R.s("\n  Report Time Step ......... %s"), .{ @as([*c]i8, &str[0]) });
    if ((Nobjects[1] > 0)) {
        datetime_timeToStr(datetime_encodeTime(0, 0, WetStep), &str[0]);
        _ = R.fprintf(Frpt.file, R.s("\n  Wet Time Step ............ %s"), .{ @as([*c]i8, &str[0]) });
        datetime_timeToStr(datetime_encodeTime(0, 0, DryStep), &str[0]);
        _ = R.fprintf(Frpt.file, R.s("\n  Dry Time Step ............ %s"), .{ @as([*c]i8, &str[0]) });
    }
    if ((Nobjects[3] > 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Routing Time Step ........ %.2f sec"), .{ @as(f64, RouteStep) });
        if ((RouteModel == 4)) {
            _ = R.fprintf(Frpt.file, R.s("\n  Variable Time Step ....... "), .{  });
            if ((CourantFactor > 0.0)) {
                _ = R.fprintf(Frpt.file, R.s("YES"), .{  });
            } else {
                _ = R.fprintf(Frpt.file, R.s("NO"), .{  });
            }
            _ = R.fprintf(Frpt.file, R.s("\n  Maximum Trials ........... %d"), .{ @as(i32, MaxTrials) });
            _ = R.fprintf(Frpt.file, R.s("\n  Number of Threads ........ %d"), .{ @as(i32, NumThreads) });
            _ = R.fprintf(Frpt.file, R.s("\n  Head Tolerance ........... %.6f "), .{ @as(f64, (HeadTol * UCF(3))) });
            if ((UnitSystem == 0)) {
                _ = R.fprintf(Frpt.file, R.s("ft"), .{  });
            } else {
                _ = R.fprintf(Frpt.file, R.s("m"), .{  });
            }
        }
    }
    report_writeLine(R.s(""));
}

// report.c:355
pub fn report_writeRainStats(i: i32, r: [*c]TRainStats) void {
    var date1: [12]i8 = std.mem.zeroes([12]i8);
    _ = &date1;
    var date2: [12]i8 = std.mem.zeroes([12]i8);
    _ = &date2;
    date1 = R.arr(12, "***********");
    date2 = R.arr(12, "***********");
    if ((RptFlags.disabled != 0)) {
        return;
    }
    if ((i < 0)) {
        report_writeLine(R.s(""));
        report_writeLine(R.s("*********************"));
        report_writeLine(R.s("Rainfall File Summary"));
        report_writeLine(R.s("*********************"));
        _ = R.fprintf(Frpt.file, R.s("\n  Station    First        Last         Recording   Periods    Periods    Periods"), .{  });
        _ = R.fprintf(Frpt.file, R.s("\n  ID         Date         Date         Frequency  w/Precip    Missing    Malfunc."), .{  });
        _ = R.fprintf(Frpt.file, R.s("\n  -------------------------------------------------------------------------------"), .{  });
    } else {
        if ((r.*.startDate != (-693594.0))) {
            datetime_dateToStr(r.*.startDate, &date1[0]);
        }
        if ((r.*.endDate != (-693594.0))) {
            datetime_dateToStr(r.*.endDate, &date2[0]);
        }
        _ = R.fprintf(Frpt.file, R.s("%-10s %10s   %-10s   %5d min    %6ld     %6ld     %6ld\n"), .{ @as([*c]i8, &((Gage[ix(i)]).staID)[0]), @as([*c]i8, &date1[0]), @as([*c]i8, &date2[0]), @as(i32, @divTrunc((Gage[ix(i)]).rainInterval, 60)), @as(i64, r.*.periodsRain), @as(i64, r.*.periodsMissing), @as(i64, r.*.periodsMalfunc) });
    }
    report_writeLine(R.s(""));
}

// report.c:396
pub fn report_writeRdiiStats(rainVol: f64, rdiiVol: f64) void {
    var ratio: f64 = 0.0;
    _ = &ratio;
    var ucf1: f64 = 0.0;
    _ = &ucf1;
    var ucf2: f64 = 0.0;
    _ = &ucf2;
    if ((RptFlags.disabled != 0)) {
        return;
    }
    ucf1 = (UCF(3) * UCF(4));
    if ((UnitSystem == 0)) {
        ucf2 = (@as(f64, 0.64632) / 86400.0);
    } else {
        ucf2 = (@as(f64, 2.4466) / 86400.0);
    }
    report_writeLine(R.s(""));
    _ = R.fprintf(Frpt.file, R.s("\n  **********************           Volume        Volume"), .{  });
    if ((UnitSystem == 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Rainfall Dependent I/I        acre-feet      10^6 gal"), .{  });
    } else {
        _ = R.fprintf(Frpt.file, R.s("\n  Rainfall Dependent I/I        hectare-m      10^6 ltr"), .{  });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  **********************        ---------     ---------"), .{  });
    _ = R.fprintf(Frpt.file, R.s("\n  Sewershed Rainfall ......%14.3f%14.3f"), .{ @as(f64, (rainVol * ucf1)), @as(f64, (rainVol * ucf2)) });
    _ = R.fprintf(Frpt.file, R.s("\n  RDII Produced ...........%14.3f%14.3f"), .{ @as(f64, (rdiiVol * ucf1)), @as(f64, (rdiiVol * ucf2)) });
    if ((rainVol == 0.0)) {
        ratio = 0.0;
    } else {
        ratio = (rdiiVol / rainVol);
    }
    _ = R.fprintf(Frpt.file, R.s("\n  RDII Ratio ..............%14.3f"), .{ @as(f64, ratio) });
    report_writeLine(R.s(""));
}

