// report.c:480
pub fn report_writeRunoffError(totals: [*c]TRunoffTotals, totalArea: f64) void {
    if ((@as(i32, Frunoff.mode) == 2)) {
        report_writeLine(R.s(""));
        _ = R.fprintf(Frpt.file, R.s("\n  **************************\n  Runoff Quantity Continuity\n  **************************\n  Runoff supplied by interface file %s"), .{ @as([*c]i8, &Frunoff.name[0]) });
        report_writeLine(R.s(""));
        return;
    }
    if ((totalArea == 0.0)) {
        return;
    }
    report_writeLine(R.s(""));
    _ = R.fprintf(Frpt.file, R.s("\n  **************************        Volume         Depth"), .{  });
    if ((UnitSystem == 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Runoff Quantity Continuity     acre-feet        inches"), .{  });
    } else {
        _ = R.fprintf(Frpt.file, R.s("\n  Runoff Quantity Continuity     hectare-m            mm"), .{  });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  **************************     ---------       -------"), .{  });
    if ((totals.*.initStorage > 0.0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Initial LID Storage ......%14.3f%14.3f"), .{ @as(f64, ((totals.*.initStorage * UCF(3)) * UCF(4))), @as(f64, ((totals.*.initStorage / totalArea) * UCF(1))) });
    }
    if ((Nobjects[13] > 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Initial Snow Cover .......%14.3f%14.3f"), .{ @as(f64, ((totals.*.initSnowCover * UCF(3)) * UCF(4))), @as(f64, ((totals.*.initSnowCover / totalArea) * UCF(1))) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Total Precipitation ......%14.3f%14.3f"), .{ @as(f64, ((totals.*.rainfall * UCF(3)) * UCF(4))), @as(f64, ((totals.*.rainfall / totalArea) * UCF(1))) });
    if ((totals.*.runon > 0.0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Outfall Runon ............%14.3f%14.3f"), .{ @as(f64, ((totals.*.runon * UCF(3)) * UCF(4))), @as(f64, ((totals.*.runon / totalArea) * UCF(1))) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Evaporation Loss .........%14.3f%14.3f"), .{ @as(f64, ((totals.*.evap * UCF(3)) * UCF(4))), @as(f64, ((totals.*.evap / totalArea) * UCF(1))) });
    _ = R.fprintf(Frpt.file, R.s("\n  Infiltration Loss ........%14.3f%14.3f"), .{ @as(f64, ((totals.*.infil * UCF(3)) * UCF(4))), @as(f64, ((totals.*.infil / totalArea) * UCF(1))) });
    _ = R.fprintf(Frpt.file, R.s("\n  Surface Runoff ...........%14.3f%14.3f"), .{ @as(f64, ((totals.*.runoff * UCF(3)) * UCF(4))), @as(f64, ((totals.*.runoff / totalArea) * UCF(1))) });
    if ((totals.*.drains > 0.0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  LID Drainage .............%14.3f%14.3f"), .{ @as(f64, ((totals.*.drains * UCF(3)) * UCF(4))), @as(f64, ((totals.*.drains / totalArea) * UCF(1))) });
    }
    if ((Nobjects[13] > 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  Snow Removed .............%14.3f%14.3f"), .{ @as(f64, ((totals.*.snowRemoved * UCF(3)) * UCF(4))), @as(f64, ((totals.*.snowRemoved / totalArea) * UCF(1))) });
        _ = R.fprintf(Frpt.file, R.s("\n  Final Snow Cover .........%14.3f%14.3f"), .{ @as(f64, ((totals.*.finalSnowCover * UCF(3)) * UCF(4))), @as(f64, ((totals.*.finalSnowCover / totalArea) * UCF(1))) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Final Storage ............%14.3f%14.3f"), .{ @as(f64, ((totals.*.finalStorage * UCF(3)) * UCF(4))), @as(f64, ((totals.*.finalStorage / totalArea) * UCF(1))) });
    _ = R.fprintf(Frpt.file, R.s("\n  Continuity Error (%%) .....%14.3f"), .{ @as(f64, totals.*.pctError) });
    report_writeLine(R.s(""));
}

// report.c:577
pub fn report_writeLoadingError(totals: [*c]TLoadingTotals) void {
    var p1: i32 = 0;
    _ = &p1;
    var p2: i32 = 0;
    _ = &p2;
    p1 = 1;
    p2 = (@as(i32, if ((5 <= Nobjects[4])) 5 else Nobjects[4]));
    while ((p1 <= Nobjects[4])) {
        report_LoadingErrors((p1 -% 1), (p2 -% 1), totals);
        p1 = (p2 +% 1);
        p2 = (p1 +% 4);
        p2 = (@as(i32, if ((p2 <= Nobjects[4])) p2 else Nobjects[4]));
    }
}

// report.c:599
fn report_LoadingErrors(p1: i32, p2: i32, totals: [*c]TLoadingTotals) void {
    var i: i32 = 0;
    _ = &i;
    var p: i32 = 0;
    _ = &p;
    var cf: f64 = 0.0;
    _ = &cf;
    var units: [15]i8 = std.mem.zeroes([15]i8);
    _ = &units;
    cf = 1.0;
    report_writeLine(R.s(""));
    _ = R.fprintf(Frpt.file, R.s("\n  **************************"), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14s"), .{ @as([*c]i8, (Pollut[ix(p)]).ID) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Runoff Quality Continuity "), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        i = UnitSystem;
        if (((Pollut[ix(p)]).units == 2)) {
            i = 2;
        }
        _ = sstrncpy(&units[0], LoadUnitsWords[ix(i)], 14);
        _ = R.fprintf(Frpt.file, R.s("%14s"), .{ @as([*c]i8, &units[0]) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  **************************"), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("    ----------"), .{  });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Initial Buildup .........."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).initLoad * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Surface Buildup .........."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).buildup * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Wet Deposition ..........."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).deposition * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Sweeping Removal ........."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).sweeping * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Infiltration Loss ........"), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).infil * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  BMP Removal .............."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).bmpRemoval * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Surface Runoff ..........."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).runoff * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Remaining Buildup ........"), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, ((totals[ix(p)]).finalLoad * cf)) });
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Continuity Error (%%) ....."), .{  });
    p = p1;
    while ((p <= p2)) : (p +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("%14.3f"), .{ @as(f64, (totals[ix(p)]).pctError) });
    }
    report_writeLine(R.s(""));
}

