    _ = R.fprintf(Frpt.file, R.s("\n  Final Stored Volume ......%14.3f%14.3f"), .{ @as(f64, (totals.*.finalStorage * ucf1)), @as(f64, (totals.*.finalStorage * ucf2)) });
