// report.c:923
pub fn report_writeMaxStats(maxMassBalErrs: [*c]TMaxStats, maxCourantCrit: [*c]TMaxStats, nMaxStats: i32) void {
    var i: i32 = 0;
    _ = &i;
    var j: i32 = 0;
    _ = &j;
    var k: i32 = 0;
    _ = &k;
    if (((RouteModel != 4) or (Nobjects[3] == 0))) {
        return;
    }
    if ((nMaxStats <= 0)) {
        return;
    }
    if ((maxMassBalErrs[0].index >= 0)) {
        report_writeLine(R.s(""));
        report_writeLine(R.s("*************************"));
        report_writeLine(R.s("Highest Continuity Errors"));
        report_writeLine(R.s("*************************"));
        i = 0;
        while ((i < nMaxStats)) : (i +%= 1) {
            j = (maxMassBalErrs[ix(i)]).index;
            if ((j < 0)) {
                continue;
            }
            _ = R.fprintf(Frpt.file, R.s("\n  Node %s (%.2f%%)"), .{ @as([*c]i8, (Node[ix(j)]).ID), @as(f64, (maxMassBalErrs[ix(i)]).value) });
        }
        report_writeLine(R.s(""));
    }
    if ((CourantFactor == 0.0)) {
        return;
    }
    report_writeLine(R.s(""));
    report_writeLine(R.s("***************************"));
    report_writeLine(R.s("Time-Step Critical Elements"));
    report_writeLine(R.s("***************************"));
    k = 0;
    i = 0;
    while ((i < nMaxStats)) : (i +%= 1) {
        j = (maxCourantCrit[ix(i)]).index;
        if ((j < 0)) {
            continue;
        }
        k +%= 1;
        if (((maxCourantCrit[ix(i)]).objType == 2)) {
            _ = R.fprintf(Frpt.file, R.s("\n  Node %s"), .{ @as([*c]i8, (Node[ix(j)]).ID) });
        } else {
            _ = R.fprintf(Frpt.file, R.s("\n  Link %s"), .{ @as([*c]i8, (Link[ix(j)]).ID) });
        }
        _ = R.fprintf(Frpt.file, R.s(" (%.2f%%)"), .{ @as(f64, (maxCourantCrit[ix(i)]).value) });
    }
    if ((k == 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n  None"), .{  });
    }
    report_writeLine(R.s(""));
}

