// report.c:1037
pub fn report_writeTimeStepStats(timeStepStats: [*c]TTimeStepStats) void {
    var timeStepCount: f64 = 0.0;
    _ = &timeStepCount;
    var totalRoutingTime: f64 = 0.0;
    _ = &totalRoutingTime;
    var fSteadyState: f64 = 0.0;
    _ = &fSteadyState;
    timeStepCount = @as(f64, @floatFromInt(timeStepStats.*.timeStepCount));
    fSteadyState = 0.0;
    if (((Nobjects[3] == 0) or (@as(f64, @floatFromInt(timeStepStats.*.timeStepCount)) == 0.0))) {
        return;
    }
    totalRoutingTime = (timeStepStats.*.steadyStateTime + timeStepStats.*.routingTime);
    if ((totalRoutingTime > 0.0)) {
        fSteadyState = ((100.0 * timeStepStats.*.steadyStateTime) / totalRoutingTime);
    }
    report_writeLine(R.s(""));
    report_writeLine(R.s("*************************"));
    report_writeLine(R.s("Routing Time Step Summary"));
    report_writeLine(R.s("*************************"));
    _ = R.fprintf(Frpt.file, R.s("\n  Minimum Time Step           :  %7.2f sec"), .{ @as(f64, timeStepStats.*.minTimeStep) });
    _ = R.fprintf(Frpt.file, R.s("\n  Average Time Step           :  %7.2f sec"), .{ @as(f64, (timeStepStats.*.routingTime / timeStepCount)) });
    _ = R.fprintf(Frpt.file, R.s("\n  Maximum Time Step           :  %7.2f sec"), .{ @as(f64, timeStepStats.*.maxTimeStep) });
    _ = R.fprintf(Frpt.file, R.s("\n  %% of Time in Steady State   :  %7.2f"), .{ @as(f64, (@as(f64, if ((fSteadyState <= 100.0)) fSteadyState else 100.0))) });
    _ = R.fprintf(Frpt.file, R.s("\n  Average Iterations per Step :  %7.2f"), .{ @as(f64, (timeStepStats.*.trialsCount / timeStepCount)) });
    _ = R.fprintf(Frpt.file, R.s("\n  %% of Steps Not Converging   :  %7.2f"), .{ @as(f64, ((100.0 * @as(f64, @floatFromInt(NonConvergeCount))) / timeStepCount)) });
    if (((RouteModel == 4) and (CourantFactor > 0.0))) {
        report_RouteStepFreq(timeStepStats);
    }
    report_writeLine(R.s(""));
}

// report.c:1085
fn report_RouteStepFreq(timeStepStats: [*c]TTimeStepStats) void {
    var totalSteps: f64 = 0.0;
    _ = &totalSteps;
    var i: i32 = 0;
    _ = &i;
    totalSteps = 0.0;
    i = 1;
    while ((i < 6)) : (i +%= 1) {
        totalSteps = (totalSteps + @as(f64, @floatFromInt((timeStepStats.*.timeStepCounts)[ix(i)])));
    }
    if ((totalSteps == 0.0)) {
        return;
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Time Step Frequencies       :"), .{  });
    i = 1;
    while ((i < 6)) : (i +%= 1) {
        _ = R.fprintf(Frpt.file, R.s("\n     %6.3f - %6.3f sec      :  %7.2f %%"), .{ @as(f64, (timeStepStats.*.timeStepIntervals)[ix((i -% 1))]), @as(f64, (timeStepStats.*.timeStepIntervals)[ix(i)]), @as(f64, ((100.0 * @as(f64, @floatFromInt(((timeStepStats.*.timeStepCounts)[ix(i)])))) / totalSteps)) });
    }
}

// report.c:1113
pub fn report_writeReport() void {
    if ((ErrorCode != 0)) {
        return;
    }
    if ((Nperiods == 0)) {
        return;
    }
    if (((@as(i32, RptFlags.subcatchments) != 0) and (((IgnoreRainfall == 0) or (IgnoreSnowmelt == 0)) or (IgnoreGwater == 0)))) {
        report_Subcatchments();
    }
    if (((IgnoreRouting == 1) and (IgnoreQuality == 1))) {
        return;
    }
    if ((@as(i32, RptFlags.nodes) != 0)) {
        report_Nodes();
    }
    if ((@as(i32, RptFlags.links) != 0)) {
        report_Links();
    }
}

// report.c:1135
fn report_Subcatchments() void {
    var j: i32 = 0;
    _ = &j;
    var p: i32 = 0;
    _ = &p;
    var k: i32 = 0;
    _ = &k;
    var period: i32 = 0;
    _ = &period;
    var days: f64 = 0.0;
    _ = &days;
    var theDate: [12]i8 = std.mem.zeroes([12]i8);
    _ = &theDate;
    var theTime: [9]i8 = std.mem.zeroes([9]i8);
    _ = &theTime;
    var hasSnowmelt: i32 = 0;
    _ = &hasSnowmelt;
    var hasGwater: i32 = 0;
    _ = &hasGwater;
    var hasQuality: i32 = 0;
    _ = &hasQuality;
    hasSnowmelt = @as(i32, @intFromBool(((Nobjects[13] > 0) and !(IgnoreSnowmelt != 0))));
    hasGwater = @as(i32, @intFromBool(((Nobjects[11] > 0) and !(IgnoreGwater != 0))));
    hasQuality = @as(i32, @intFromBool(((Nobjects[4] > 0) and !(IgnoreQuality != 0))));
    if ((Nobjects[1] == 0)) {
        return;
    }
    report_writeLine(R.s(""));
    report_writeLine(R.s("********************************"));
    report_writeLine(R.s("Subcatchment Time Series Results"));
    report_writeLine(R.s("********************************"));
    j = 0;
    while ((j < Nobjects[1])) : (j +%= 1) {
        k = ((Subcatch[ix(j)]).rptFlag -% 1);
        if ((k >= 0)) {
            report_SubcatchHeader((Subcatch[ix(j)]).ID);
            period = 1;
            while ((@as(i64, period) <= Nperiods)) : (period +%= 1) {
                output_readDateTime(@as(i64, period), &days);
                datetime_dateToStr(days, &theDate[0]);
                datetime_timeToStr(days, &theTime[0]);
                output_readSubcatchResults(@as(i64, period), k);
                _ = R.fprintf(Frpt.file, R.s("\n  %11s %8s %10.3f%10.3f%10.4f"), .{ @as([*c]i8, &theDate[0]), @as([*c]i8, &theTime[0]), @as(f64, @as(f64, SubcatchResults[0])), @as(f64, ((@as(f64, SubcatchResults[2]) / 24.0) + @as(f64, SubcatchResults[3]))), @as(f64, @as(f64, SubcatchResults[4])) });
                if ((hasSnowmelt != 0)) {
                    _ = R.fprintf(Frpt.file, R.s("  %10.3f"), .{ @as(f64, @as(f64, SubcatchResults[1])) });
                }
                if ((hasGwater != 0)) {
                    _ = R.fprintf(Frpt.file, R.s("%10.3f%10.4f"), .{ @as(f64, @as(f64, SubcatchResults[6])), @as(f64, @as(f64, SubcatchResults[5])) });
                }
                if ((hasQuality != 0)) {
                    p = 0;
                    while ((p < Nobjects[4])) : (p +%= 1) {
                        _ = R.fprintf(Frpt.file, R.s("%10.3f"), .{ @as(f64, @as(f64, SubcatchResults[ix((8 +% p))])) });
                    }
                }
            }
            report_writeLine(R.s(""));
        }
    }
}

// report.c:1192
fn report_SubcatchHeader(id: [*c]i8) void {
    var i: i32 = 0;
    _ = &i;
    var hasSnowmelt: i32 = 0;
    _ = &hasSnowmelt;
    var hasGwater: i32 = 0;
    _ = &hasGwater;
    var hasQuality: i32 = 0;
    _ = &hasQuality;
    hasSnowmelt = @as(i32, @intFromBool(((Nobjects[13] > 0) and !(IgnoreSnowmelt != 0))));
    hasGwater = @as(i32, @intFromBool(((Nobjects[11] > 0) and !(IgnoreGwater != 0))));
    hasQuality = @as(i32, @intFromBool(((Nobjects[4] > 0) and !(IgnoreQuality != 0))));
    report_writeLine(R.s(""));
    _ = R.fprintf(Frpt.file, R.s("\n  <<< Subcatchment %s >>>"), .{ @as([*c]i8, id) });
    report_writeLine(R.s("---------------------------------------------------"));
    if ((hasSnowmelt > 0)) {
        _ = R.fprintf(Frpt.file, R.s("------------"), .{  });
    }
    if ((hasGwater != 0)) {
        _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
        _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
    }
    if ((hasQuality != 0)) {
        i = 0;
        while ((i < Nobjects[4])) : (i +%= 1) {
            _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
        }
    }
    _ = R.fprintf(Frpt.file, R.s("\n  Date        Time        Precip.    Losses    Runoff"), .{  });
    if ((hasSnowmelt != 0)) {
        _ = R.fprintf(Frpt.file, R.s("  Snow Depth"), .{  });
    }
    if ((hasGwater != 0)) {
        _ = R.fprintf(Frpt.file, R.s("  GW Elev.   GW Flow"), .{  });
    }
    if ((hasQuality != 0)) {
        i = 0;
        while ((i < Nobjects[4])) : (i +%= 1) {
            _ = R.fprintf(Frpt.file, R.s("%10s"), .{ @as([*c]i8, (Pollut[ix(i)]).ID) });
        }
    }
    if ((UnitSystem == 0)) {
        _ = R.fprintf(Frpt.file, R.s("\n                            in/hr     in/hr %9s"), .{ @as([*c]i8, FlowUnitWords[ix(FlowUnits)]) });
    } else {
        _ = R.fprintf(Frpt.file, R.s("\n                            mm/hr     mm/hr %9s"), .{ @as([*c]i8, FlowUnitWords[ix(FlowUnits)]) });
    }
    if ((hasSnowmelt != 0)) {
        if ((UnitSystem == 0)) {
            _ = R.fprintf(Frpt.file, R.s("      inches"), .{  });
        } else {
            _ = R.fprintf(Frpt.file, R.s("     mmeters"), .{  });
        }
    }
    if ((hasGwater != 0)) {
        if ((UnitSystem == 0)) {
            _ = R.fprintf(Frpt.file, R.s("      feet %9s"), .{ @as([*c]i8, FlowUnitWords[ix(FlowUnits)]) });
        } else {
            _ = R.fprintf(Frpt.file, R.s("    meters %9s"), .{ @as([*c]i8, FlowUnitWords[ix(FlowUnits)]) });
        }
    }
    if ((hasQuality != 0)) {
        i = 0;
        while ((i < Nobjects[4])) : (i +%= 1) {
            _ = R.fprintf(Frpt.file, R.s("%10s"), .{ @as([*c]i8, QualUnitsWords[ix((Pollut[ix(i)]).units)]) });
        }
    }
    report_writeLine(R.s("---------------------------------------------------"));
    if ((hasSnowmelt != 0)) {
        _ = R.fprintf(Frpt.file, R.s("------------"), .{  });
    }
    if ((hasGwater != 0)) {
        _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
        _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
    }
    if ((hasQuality != 0)) {
        i = 0;
        while ((i < Nobjects[4])) : (i +%= 1) {
            _ = R.fprintf(Frpt.file, R.s("----------"), .{  });
        }
    }
}

