fn report_Nodes() void {
    var j: i32 = 0;
    _ = &j;
    var p: i32 = 0;
    _ = &p;
    var k: i32 = 0;
    _ = &k;
    var period: i32 = 0;
    _ = &period;
    var days: f64 = 0.0;
    _ = &days;
    var theDate: [12]i8 = std.mem.zeroes([12]i8);
    _ = &theDate;
    var theTime: [9]i8 = std.mem.zeroes([9]i8);
    _ = &theTime;
    if ((Nobjects[2] == 0)) {
        return;
    }
    report_writeLine(R.s(""));
    report_writeLine(R.s("************************"));
    report_writeLine(R.s("Node Time Series Results"));
    report_writeLine(R.s("************************"));
    j = 0;
    while ((j < Nobjects[2])) : (j +%= 1) {
        k = ((Node[ix(j)]).rptFlag -% 1);
        if ((k >= 0)) {
            report_NodeHeader((Node[ix(j)]).ID);
            period = 1;
            while ((@as(i64, period) <= Nperiods)) : (period +%= 1) {
                output_readDateTime(@as(i64, period), &days);
                datetime_dateToStr(days, &theDate[0]);
