// roadway.c:85
pub fn roadway_getInflow(j: i32, dir: f64, hRoad: f64, h1: f64, h2: f64) f64 {
    var k: i32 = 0;
    _ = &k;
    var roadSurf: i32 = 0;
    _ = &roadSurf;
    var useVariableCd: i32 = 0;
    _ = &useVariableCd;
    var length: f64 = 0.0;
    _ = &length;
    var roadWidth: f64 = 0.0;
    _ = &roadWidth;
    var hWr: f64 = 0.0;
    _ = &hWr;
    var ht: f64 = 0.0;
    _ = &ht;
    var cD: f64 = 0.0;
    _ = &cD;
    var q: f64 = 0.0;
    _ = &q;
    var dqdh: f64 = 0.0;
    _ = &dqdh;
    q = 0.0;
    dqdh = 0.0;
    if (((Link[ix(j)]).type != 3)) {
        return 0.0;
    }
    k = (Link[ix(j)]).subIndex;
    roadWidth = (Weir[ix(k)]).roadWidth;
    roadSurf = (Weir[ix(k)]).roadSurface;
    cD = (Weir[ix(k)]).cDisch1;
    if ((UnitSystem == 1)) {
        cD = (cD / 0.552);
    }
    useVariableCd = 0;
    if (((roadWidth > 0.0) and (roadSurf >= 1))) {
        useVariableCd = 1;
    }
    hWr = (h1 - hRoad);
    ht = (h2 - hRoad);
    if ((hWr > 0.0001)) {
        if ((useVariableCd != 0)) {
            cD = getCd(hWr, ht, roadWidth, roadSurf);
        }
        length = ((Link[ix(j)]).xsect).wMax;
        q = ((cD * length) * R.pow(hWr, 1.5));
        dqdh = ((1.5 * q) / hWr);
    }
    (Link[ix(j)]).dqdh = dqdh;
    (Link[ix(j)]).newDepth = (@as(f64, if (((h1 - hRoad) >= 0.0)) (h1 - hRoad) else 0.0));
    (Link[ix(j)]).flowClass = 3;
    if ((hRoad > h2)) {
        if ((dir == 1.0)) {
            (Link[ix(j)]).flowClass = 6;
        } else {
            (Link[ix(j)]).flowClass = 5;
        }
    }
    return (dir * q);
}

// roadway.c:146
fn getCd(hWr: f64, ht: f64, roadWidth: f64, roadSurf: i32) f64 {
    var kT: f64 = 0.0;
    _ = &kT;
    var hL: f64 = 0.0;
    _ = &hL;
    var htH: f64 = 0.0;
    _ = &htH;
    var cR: f64 = 0.0;
    _ = &cR;
    kT = 1.0;
    if ((hWr <= 0.0)) {
        return 0.0;
    }
    hL = (hWr / roadWidth);
    if ((hL <= 0.15)) {
        if ((roadSurf == 1)) {
            cR = getY(hWr, @as([*c][2]f64, @ptrCast(@alignCast(&Cr_Low_Paved[0]))), N_Cr_Low_Paved);
        } else {
            cR = getY(hWr, @as([*c][2]f64, @ptrCast(@alignCast(&Cr_Low_Gravel[0]))), N_Cr_Low_Gravel);
        }
    } else {
        if ((roadSurf == 1)) {
            cR = getY(hL, @as([*c][2]f64, @ptrCast(@alignCast(&Cr_High_Paved[0]))), N_Cr_High_Paved);
        } else {
            cR = getY(hL, @as([*c][2]f64, @ptrCast(@alignCast(&Cr_High_Gravel[0]))), N_Cr_High_Gravel);
        }
    }
    if ((ht > 0.0)) {
        htH = (ht / hWr);
        if ((roadSurf == 1)) {
            kT = getY(htH, @as([*c][2]f64, @ptrCast(@alignCast(&Kt_Paved[0]))), N_Kt_Paved);
        } else {
            kT = getY(htH, @as([*c][2]f64, @ptrCast(@alignCast(&Kt_Gravel[0]))), N_Kt_Gravel);
        }
    }
    return (cR * kT);
}

// roadway.c:176
fn getY(x: f64, table: [*c][2]f64, n_2: i32) f64 {
    var i: i32 = 0;
    _ = &i;
    var x1: f64 = 0.0;
    _ = &x1;
    var y1: f64 = 0.0;
    _ = &y1;
    var dx: f64 = 0.0;
    _ = &dx;
    var dy: f64 = 0.0;
    _ = &dy;
    if ((x <= table[0][0])) {
        return table[0][1];
    }
    if ((x >= (table[ix((n_2 -% 1))])[0])) {
        return (table[ix((n_2 -% 1))])[1];
    }
    i = 1;
    while ((i < n_2)) : (i +%= 1) {
        if ((x <= (table[ix(i)])[0])) {
            x1 = (table[ix((i -% 1))])[0];
            dx = ((table[ix(i)])[0] - x1);
            y1 = (table[ix((i -% 1))])[1];
            dy = ((table[ix(i)])[1] - y1);
            return (y1 + (((x - x1) * dy) / dx));
        }
    }
    return (table[ix((n_2 -% 1))])[1];
}

// routing.c:93
pub fn routing_open() i32 {
    if (!(treatmnt_open() != 0)) {
        return ErrorCode;
    }
    SortedLinks = null;
    if ((Nobjects[3] > 0)) {
        SortedLinks = @as([*c]i32, @ptrCast(@alignCast(R.calloc(@as(u64, @bitCast(@as(i64, Nobjects[3]))), 4))));
        if (!(SortedLinks != null)) {
            report_writeErrorMsg(101, R.s(""));
            return ErrorCode;
        }
        toposort_sortLinks(SortedLinks);
        if ((ErrorCode != 0)) {
            return ErrorCode;
        }
    }
    iface_openRoutingFiles();
    flowrout_init(RouteModel);
    if ((@as(i32, Fhotstart1.mode) == 0)) {
        qualrout_init();
    }
    if ((NumEvents > 0)) {
        sortEvents();
    }
    NextEvent = 0;
    BetweenEvents = @as(i32, @intFromBool((NumEvents > 0)));
    NewRuleTime = 0.0;
    return ErrorCode;
}

