// routing.c:152
pub fn routing_getRoutingStep(routingModel: i32, fixedStep: f64) f64 {
    var date1: f64 = 0.0;
    _ = &date1;
    var date2: f64 = 0.0;
    _ = &date2;
    var nextTime: f64 = 0.0;
    _ = &nextTime;
    var routingStep: f64 = 0.0;
    _ = &routingStep;
    var nextRuleTime: f64 = 0.0;
    _ = &nextRuleTime;
    var nextRoutingTime: f64 = 0.0;
    _ = &nextRoutingTime;
    routingStep = 0.0;
    if ((Nobjects[3] == 0)) {
        return fixedStep;
    }
    if (((NumEvents > 0) and (BetweenEvents != 0))) {
        nextTime = (@as(f64, if ((NewRunoffTime <= ReportTime)) NewRunoffTime else ReportTime));
        date1 = getDateTime(NewRoutingTime);
        date2 = getDateTime(nextTime);
        if (((date2 > date1) and (date2 < (Event[ix(NextEvent)]).start))) {
            routingStep = ((nextTime - NewRoutingTime) / 1000.0);
        } else {
            date1 = getDateTime((NewRoutingTime + (1000.0 * fixedStep)));
            if ((date1 < (Event[ix(NextEvent)]).start)) {
                return fixedStep;
            }
        }
    }
    if ((routingStep == 0.0)) {
        routingStep = flowrout_getRoutingStep(routingModel, fixedStep);
    }
    if ((RuleStep > 0)) {
        nextRuleTime = (NewRuleTime + (1000.0 * @as(f64, @floatFromInt(RuleStep))));
        nextRoutingTime = (NewRoutingTime + (1000.0 * routingStep));
        if ((nextRoutingTime >= nextRuleTime)) {
            routingStep = ((nextRuleTime - NewRoutingTime) / 1000.0);
        }
    }
    return routingStep;
}

// routing.c:203
pub fn routing_execute(routingModel: i32, routingStep: f64) void {
    var trialsCount: i32 = 0;
    _ = &trialsCount;
    var actionCount: i32 = 0;
    _ = &actionCount;
    var inSteadyState: i32 = 0;
    _ = &inSteadyState;
    var currentDate: f64 = 0.0;
    _ = &currentDate;
    var stepFlowError: f64 = 0.0;
    _ = &stepFlowError;
    trialsCount = 1;
    actionCount = 0;
    inSteadyState = 1;
    if ((ErrorCode != 0)) {
        return;
    }
    massbal_updateRoutingTotals((routingStep / 2.0));
    currentDate = getDateTime(NewRoutingTime);
    actionCount = evaluateControlRules(currentDate, routingStep);
    stepFlowError = massbal_getStepFlowError();
    massbal_initTimeStepTotals();
    initSystemInflows();
    BetweenEvents = isBetweenEvents(currentDate);
    if ((BetweenEvents == 0)) {
        addSystemInflows(currentDate, routingStep);
        inlet_findCapturedFlows(routingStep);
        inSteadyState = isInSteadyState(actionCount, stepFlowError);
        if ((inSteadyState == 0)) {
            trialsCount = routeFlow(routingModel, routingStep);
        }
        if (((Nobjects[4] > 0) and !(IgnoreQuality != 0))) {
            inlet_adjustQualInflows();
            qualrout_execute(routingStep);
        }
        removeSystemOutflows(routingStep);
        inlet_adjustQualOutflows();
        if ((Nobjects[3] > 0)) {
            stats_updateFlowStats(routingStep, getDateTime(NewRoutingTime));
            stats_updateTimeStepStats(routingStep, trialsCount, inSteadyState);
        }
    }
    massbal_updateRoutingTotals((routingStep / 2.0));
}

