        if (((Link[ix(j)]).targetSetting != (Link[ix(j)]).setting)) {
            if ((((Link[ix(j)]).targetSetting * (Link[ix(j)]).setting) == 0.0)) {
                (Link[ix(j)]).timeLastSet = currentDate;
            }
            link_setSetting(j, routingStep);
