fn stats_findMaxStats() void {
    var j: i32 = 0;
    _ = &j;
    var x: f64 = 0.0;
    _ = &x;
    var z: f64 = 0.0;
    _ = &z;
    var stepCount: f64 = 0.0;
    _ = &stepCount;
    j = 0;
    while ((j < 5)) : (j +%= 1) {
        (MaxMassBalErrs[ix(j)]).objType = 2;
        (MaxMassBalErrs[ix(j)]).index = (-1);
        (MaxMassBalErrs[ix(j)]).value = (-1.0);
        (MaxCourantCrit[ix(j)]).index = (-1);
        (MaxCourantCrit[ix(j)]).value = (-1.0);
        (MaxFlowTurns[ix(j)]).index = (-1);
        (MaxFlowTurns[ix(j)]).value = (-1.0);
        (MaxNonConverged[ix(j)]).index = (-1);
        (MaxNonConverged[ix(j)]).value = 0.0;
    }
    if ((ReportStepCount > 2)) {
        stepCount = @as(f64, @floatFromInt(ReportStepCount));
        z = (100.0 / ((@as(f64, 2.0) / 3.0) * (stepCount - 2.0)));
        j = 0;
        while ((j < Nobjects[3])) : (j +%= 1) {
            x = (@as(f64, @floatFromInt((LinkStats[ix(j)]).flowTurns)) * z);
            stats_updateMaxStats(&MaxFlowTurns[0], 3, j, x);
        }
    }
    j = 0;
    while ((j < Nobjects[2])) : (j +%= 1) {
        if (((Node[ix(j)]).degree <= 0)) {
            continue;
        }
        if ((NodeInflow[ix(j)] <= 0.1)) {
            continue;
        }
        if ((NodeInflow[ix(j)] > 0.0)) {
            x = (1.0 - (NodeOutflow[ix(j)] / NodeInflow[ix(j)]));
        } else if ((NodeOutflow[ix(j)] > 0.0)) {
            x = (-1.0);
        } else {
            x = 0.0;
        }
        stats_updateMaxStats(&MaxMassBalErrs[0], 2, j, (100.0 * x));
    }
    stepCount = @as(f64, @floatFromInt(TimeStepStats.timeStepCount));
    if ((RouteModel == 4)) {
        j = 0;
        while ((j < Nobjects[2])) : (j +%= 1) {
            stats_updateMaxStats(&MaxNonConverged[0], 2, j, (@as(f64, @floatFromInt((NodeStats[ix(j)]).nonConvergedCount)) / stepCount));
        }
    }
    if (((RouteModel != 4) or (CourantFactor == 0.0))) {
        return;
    }
    if ((stepCount == 0.0)) {
        return;
    }
    j = 0;
    while ((j < Nobjects[2])) : (j +%= 1) {
        x = ((NodeStats[ix(j)]).timeCourantCritical / stepCount);
        stats_updateMaxStats(&MaxCourantCrit[0], 2, j, (100.0 * x));
    }
    j = 0;
    while ((j < Nobjects[3])) : (j +%= 1) {
        x = ((LinkStats[ix(j)]).timeCourantCritical / stepCount);
