// stats.c:841
fn stats_updateMaxStats(maxStats: [*c]TMaxStats, i: i32, j: i32, x: f64) void {
    var k: i32 = 0;
    _ = &k;
    var maxStats1: TMaxStats = std.mem.zeroes(TMaxStats);
    _ = &maxStats1;
    var maxStats2: TMaxStats = std.mem.zeroes(TMaxStats);
    _ = &maxStats2;
    maxStats1.objType = i;
    maxStats1.index = j;
    maxStats1.value = x;
    k = 0;
    while ((k < 5)) : (k +%= 1) {
        if ((@abs(maxStats1.value) > @abs((maxStats[ix(k)]).value))) {
            maxStats2 = maxStats[ix(k)];
            maxStats[ix(k)] = maxStats1;
            maxStats1 = maxStats2;
        }
    }
}

// statsrpt.c:84
pub fn statsrpt_writeReport() void {
    if (((FlowUnits == 2) or (FlowUnits == 3))) {
        _ = sstrncpy(&FlowFmt[0], R.s("%9.3f"), 5);
    } else {
        _ = sstrncpy(&FlowFmt[0], R.s("%9.2f"), 5);
    }
    if ((UnitSystem == 0)) {
        Vcf = (@as(f64, 7.48) / 1000000.0);
    } else {
        Vcf = (@as(f64, 28.317) / 1000000.0);
    }
    if ((Nobjects[1] > 0)) {
        if (((!(IgnoreRainfall != 0) or ((Nobjects[13] > 0) and !(IgnoreSnowmelt != 0))) or ((Nobjects[11] > 0) and !(IgnoreGwater != 0)))) {
            writeSubcatchRunoff();
            lid_writeWaterBalance();
            if (!(IgnoreGwater != 0)) {
                writeGroundwater();
            }
            if (((Nobjects[4] > 0) and !(IgnoreQuality != 0))) {
                writeSubcatchLoads();
            }
        }
    }
    if (((Nobjects[3] > 0) and !(IgnoreRouting != 0))) {
        writeNodeDepths();
        writeNodeFlows();
        if ((RouteModel == 4)) {
            writeNodeSurcharge();
        }
        writeNodeFlooding();
        writeStorageVolumes();
        writeOutfallLoads();
        inlet_writeStatsReport();
        writeLinkFlows();
        writeFlowClass();
        writeLinkSurcharge();
        writePumpFlows();
        if (((Nobjects[4] > 0) and !(IgnoreQuality != 0))) {
            writeLinkLoads();
        }
    }
}

