        _ = R.fprintf(Frpt.file, R.s(" %-9s"), .{ @as([*c]i8, NodeTypeWords[ix((Node[ix(j)]).type)]) });
        d1 = (((NodeStats[ix(j)]).maxDepth + (Node[ix(j)]).invertElev) - (Node[ix(j)]).crownElev);
