        }
        if ((n_2 == 0)) {
            _ = R.fprintf(Frpt.file, R.s("\n  ----------------------------------------------------------------------------\n                                                           Hours        Hours \n                         --------- Hours Full --------   Above Full   Capacity\n  Conduit                Both Ends  Upstream  Dnstream   Normal Flow   Limited\n  ----------------------------------------------------------------------------"), .{  });
