        _ = R.fprintf(Frpt.file, R.s("    %8.2f  %8.2f  %8.2f  %8.2f     %8.2f"), .{ @as(f64, t[0]), @as(f64, t[1]), @as(f64, t[2]), @as(f64, t[3]), @as(f64, t[4]) });
    }
    if ((n_2 == 0)) {
