                    if ((@rem((ntoks -% 1), 2) > 0)) {
                        return error_setInpError(203, R.s(""));
                    }
                    i = 1;
                    while ((i < ntoks)) {
                        if (!(getDouble(tok[ix(i)], &x[1]) != 0)) {
                            return error_setInpError(211, tok[ix(i)]);
                        }
                        if (!(getDouble(tok[ix((i +% 1))], &x[2]) != 0)) {
                            return error_setInpError(211, tok[ix((i +% 1))]);
                        }
                        errcode = addStation(x[1], x[2]);
                        if ((errcode != 0)) {
                            return errcode;
                        }
                        i +%= 2;
                    }
                    return 0;
        },
        else => {},
    }
    return 0;
}

// transect.c:194
pub fn transect_validate(j: i32) void {
    var i: i32 = 0;
    _ = &i;
    var ymin: f64 = 0.0;
    _ = &ymin;
    var ymax: f64 = 0.0;
    _ = &ymax;
    var oldNchannel: f64 = 0.0;
    _ = &oldNchannel;
    oldNchannel = Nchannel;
    if (((j < 0) or (j >= Ntransects))) {
        return;
    }
    if ((Nstations < 2)) {
        report_writeErrorMsg(223, (Transect[ix(j)]).ID);
        return;
    }
    if ((Nstations >= 1500)) {
        report_writeErrorMsg(225, (Transect[ix(j)]).ID);
        return;
    }
    if ((Nchannel <= 0.0)) {
        report_writeErrorMsg(227, (Transect[ix(j)]).ID);
        return;
    }
    if ((Xleftbank > Xrightbank)) {
        report_writeErrorMsg(229, (Transect[ix(j)]).ID);
        return;
    }
    Nchannel = (Nchannel * @sqrt(Lfactor));
    (Transect[ix(j)]).lengthFactor = Lfactor;
    ymax = Elev[1];
    ymin = Elev[1];
    i = 2;
    while ((i <= Nstations)) : (i +%= 1) {
        ymax = (@as(f64, if (((Elev[ix(i)]) >= ymax)) (Elev[ix(i)]) else ymax));
        ymin = (@as(f64, if (((Elev[ix(i)]) <= ymin)) (Elev[ix(i)]) else ymin));
    }
    if ((ymin >= ymax)) {
        report_writeErrorMsg(231, (Transect[ix(j)]).ID);
        return;
    }
    Station[0] = Station[1];
    Elev[0] = ymax;
    Nstations +%= 1;
    Station[ix(Nstations)] = Station[ix((Nstations -% 1))];
    Elev[ix(Nstations)] = Elev[0];
    (Transect[ix(j)]).nTbl = 51;
    createTables(&(Transect[ix(j)]), ymin, ymax);
    (Transect[ix(j)]).roughness = oldNchannel;
}

// transect.c:264
fn createTables(transect: [*c]TTransect, ymin: f64, ymax: f64) void {
    var i: i32 = 0;
    _ = &i;
    var nLast: i32 = 0;
    _ = &nLast;
    var dy: f64 = 0.0;
    _ = &dy;
    var y_2: f64 = 0.0;
    _ = &y_2;
    transect.*.yFull = (ymax - ymin);
    transect.*.wMax = 0.0;
    (transect.*.areaTbl)[0] = 0.0;
    (transect.*.hradTbl)[0] = 0.0;
    (transect.*.widthTbl)[0] = 0.0;
    dy = ((ymax - ymin) / (@as(f64, @floatFromInt((transect.*.nTbl))) - 1.0));
    y_2 = ymin;
    i = 1;
    while ((i < transect.*.nTbl)) : (i +%= 1) {
        y_2 = (y_2 + dy);
        (transect.*.areaTbl)[ix(i)] = 0.0;
        (transect.*.hradTbl)[ix(i)] = 0.0;
        (transect.*.widthTbl)[ix(i)] = 0.0;
        getGeometry(transect, i, y_2);
    }
    setMaxSectionFactor(transect);
    nLast = (transect.*.nTbl -% 1);
    transect.*.aFull = (transect.*.areaTbl)[ix(nLast)];
    transect.*.rFull = (transect.*.hradTbl)[ix(nLast)];
    transect.*.wMax = (transect.*.widthTbl)[ix(nLast)];
    i = 1;
    while ((i <= nLast)) : (i +%= 1) {
        (transect.*.areaTbl)[ix(i)] = ((transect.*.areaTbl)[ix(i)] / transect.*.aFull);
        (transect.*.hradTbl)[ix(i)] = ((transect.*.hradTbl)[ix(i)] / transect.*.rFull);
        (transect.*.widthTbl)[ix(i)] = ((transect.*.widthTbl)[ix(i)] / transect.*.wMax);
    }
    (transect.*.widthTbl)[0] = (transect.*.widthTbl)[1];
}

