// transect.c:334
fn setParams(j: i32, id: [*c]i8, x: [*c]f64) i32 {
    if (((j < 0) or (j >= Ntransects))) {
        return 211;
    }
    (Transect[ix(j)]).ID = id;
    Xleftbank = (x[3] / UCF(3));
    Xrightbank = (x[4] / UCF(3));
    Lfactor = x[7];
    if ((Lfactor == 0.0)) {
        Lfactor = 1.0;
    }
    Xfactor = x[8];
    if ((Xfactor == 0.0)) {
        Xfactor = 1.0;
    }
    Xleftbank = (Xleftbank * Xfactor);
    Xrightbank = (Xrightbank * Xfactor);
    Yfactor = (x[9] / UCF(3));
    Nstations = 0;
    return 0;
}

// transect.c:360
fn addStation(y_2: f64, x: f64) i32 {
    if ((Nstations < 0)) {
        return 219;
    }
    Nstations +%= 1;
    if ((Nstations >= 1500)) {
        return 0;
    }
    Station[ix(Nstations)] = ((x * Xfactor) / UCF(3));
    Elev[ix(Nstations)] = ((y_2 + Yfactor) / UCF(3));
    if (((Nstations > 1) and (Station[ix(Nstations)] < Station[ix((Nstations -% 1))]))) {
        return 221;
    }
    return 0;
}

// transect.c:388
fn getGeometry(transect: [*c]TTransect, i: i32, y_2: f64) void {
    var k: i32 = 0;
    _ = &k;
    var ylo: f64 = 0.0;
    _ = &ylo;
    var yhi: f64 = 0.0;
    _ = &yhi;
    var w: f64 = 0.0;
    _ = &w;
    var wp: f64 = 0.0;
    _ = &wp;
    var wpSum: f64 = 0.0;
    _ = &wpSum;
    var a_2: f64 = 0.0;
    _ = &a_2;
    var aSum: f64 = 0.0;
    _ = &aSum;
    var q: f64 = 0.0;
    _ = &q;
    var qSum: f64 = 0.0;
    _ = &qSum;
    var findFlow: i32 = 0;
    _ = &findFlow;
    wpSum = 0.0;
    aSum = 0.0;
    qSum = 0.0;
    k = 1;
    while ((k <= Nstations)) : (k +%= 1) {
        if ((Elev[ix((k -% 1))] >= Elev[ix(k)])) {
            yhi = Elev[ix((k -% 1))];
            ylo = Elev[ix(k)];
        } else {
            yhi = Elev[ix(k)];
            ylo = Elev[ix((k -% 1))];
        }
        if ((ylo >= y_2)) {
            continue;
        }
        getSliceGeom(k, y_2, ylo, yhi, &w, &a_2, &wp);
        wpSum = (wpSum + wp);
        aSum = (aSum + a_2);
        (transect.*.areaTbl)[ix(i)] = ((transect.*.areaTbl)[ix(i)] + a_2);
        (transect.*.widthTbl)[ix(i)] = ((transect.*.widthTbl)[ix(i)] + w);
        if ((Elev[ix(k)] >= y_2)) {
            findFlow = 1;
        } else {
            findFlow = 0;
        }
        q = getFlow(k, aSum, wpSum, findFlow);
        if ((q > 0.0)) {
            qSum = (qSum + q);
            aSum = 0.0;
            wpSum = 0.0;
        }
    }
    aSum = (transect.*.areaTbl)[ix(i)];
    if ((aSum == 0.0)) {
        (transect.*.hradTbl)[ix(i)] = (transect.*.hradTbl)[ix((i -% 1))];
    } else {
        (transect.*.hradTbl)[ix(i)] = R.pow((((qSum * Nchannel) / 1.49) / aSum), 1.5);
    }
}

