fn getSliceGeom(k: i32, y_2: f64, ylo: f64, yhi: f64, w: [*c]f64, a_2: [*c]f64, wp: [*c]f64) void {
    var width: f64 = 0.0;
    _ = &width;
    var ratio: f64 = 0.0;
    _ = &ratio;
