// xsect.c:714
pub fn xsect_getSofA(xsect_2: [*c]TXsect, a_2: f64) f64 {
    var alpha: f64 = 0.0;
    _ = &alpha;
    var r: f64 = 0.0;
    _ = &r;
    alpha = (a_2 / xsect_2.*.aFull);
    switch (xsect_2.*.type) {
        FORCE_MAIN, CIRCULAR => {
                    return circ_getSofA(xsect_2, a_2);
        },
        EGGSHAPED => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_Egg[0], N_S_Egg));
        },
        HORSESHOE => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_Horseshoe[0], N_S_Horseshoe));
        },
        GOTHIC => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_Gothic[0], N_S_Gothic));
        },
        CATENARY => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_Catenary[0], N_S_Catenary));
        },
        SEMIELLIPTICAL => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_SemiEllip[0], N_S_SemiEllip));
        },
        BASKETHANDLE => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_BasketHandle[0], N_S_BasketHandle));
        },
        SEMICIRCULAR => {
                    return (xsect_2.*.sFull * lookup(alpha, &S_SemiCirc[0], N_S_SemiCirc));
        },
        RECT_CLOSED => {
                    return rect_closed_getSofA(xsect_2, a_2);
        },
        RECT_OPEN => {
                    return rect_open_getSofA(xsect_2, a_2);
        },
        RECT_TRIANG => {
                    return rect_triang_getSofA(xsect_2, a_2);
        },
        RECT_ROUND => {
                    return rect_round_getSofA(xsect_2, a_2);
        },
        else => {
                    if ((a_2 == 0.0)) {
                        return 0.0;
                    }
                    r = xsect_getRofA(xsect_2, a_2);
                    if ((r < 1e-06)) {
                        return 0.0;
                    }
                    return (a_2 * R.pow(r, (@as(f64, 2.0) / 3.0)));
        },
    }
}

