    xsect_2.*.rFull = transect.*.rFull;
    xsect_2.*.sFull = (xsect_2.*.aFull * R.pow(xsect_2.*.rFull, (@as(f64, 2.0) / 3.0)));
    xsect_2.*.sMax = transect.*.sMax;
