    var k: i32 = 0;
    _ = &k;
    var theta: f64 = 0.0;
    _ = &theta;
    var theta1: f64 = 0.0;
    _ = &theta1;
    var ap: f64 = 0.0;
    _ = &ap;
    var tt: f64 = 0.0;
    _ = &tt;
    var tt23: f64 = 0.0;
    _ = &tt23;
    var t3: f64 = 0.0;
    _ = &t3;
    var d: f64 = 0.0;
    _ = &d;
    if ((psi > 0.9)) {
        theta = (4.17 + ((1.12 * (psi - 0.9)) / 0.176));
    } else if ((psi > 0.5)) {
        theta = (3.14 + ((1.03 * (psi - 0.5)) / 0.4));
    } else if ((psi > 0.015)) {
        theta = (1.2 + ((1.94 * (psi - 0.015)) / 0.485));
    } else {
        theta = ((0.12103 - (55.5075 * psi)) + (15.62254 * @sqrt(psi)));
    }
    theta1 = theta;
    ap = ((@as(f64, 2.0) * 3.141592654) * psi);
    k = 1;
    while ((k <= 40)) : (k +%= 1) {
        theta = @abs(theta);
        tt = (theta - R.sin(theta));
        tt23 = R.pow(tt, (@as(f64, 2.0) / 3.0));
        t3 = R.pow(theta, (@as(f64, 1.0) / 3.0));
        d = (((ap * theta) / t3) - (tt * tt23));
        d = (d / (((ap * (@as(f64, 2.0) / 3.0)) / t3) - (((@as(f64, 5.0) / 3.0) * tt23) * (1.0 - R.cos(theta)))));
        theta = (theta - d);
        if ((@abs(d) <= 0.0001)) {
            return theta;
        }
    }
    return theta1;
}

